svg.script:
//
//!export-start
let _ps_stationA_pt = "0.00";    // PT-01 Kesinga intake pressure, bar
let _ps_stationB_pt2 = "0.00";   // PT-02 Lanjigarh inlet pressure, bar
let _ps_stationB_pt3 = "0.00";    // PT-03 Lanjigarh discharge pressure, bar
let _ps_stationC_pt = "0.00";     // PT-04 reservoir pressure, bar
let _pn_stationA_flow = 0;        // Station A existing flow meter, m3/h
let _pn_stationB_flow = 0;       // FM-01 Lanjigarh flow, m3/h
let _pn_stationC_flow = 0;       // Station C reservoir flow, m3/h
let _pn_stationB_level = 0;      // LT-01 Lanjigarh tank level, %
let _pb_pumpA_run = false;      // Station A pump running feedback
let _pb_pumpB_run = false;      // Station B pump running feedback
let _pb_pumpA_cmd = false;      // Station A pump start/stop command (click on pump symbol)
let _pb_pumpB_cmd = false;      // Station B pump start/stop command (click on pump symbol)
let _pb_commA = false;          // Station A edge device comm link online
let _pb_commB = false;          // Station B edge device comm link online
let _pb_commC = false;          // Station C edge device comm link online
//!export-end

var COL_ALARM = '#E53935';
var COL_NORMAL = '#475CA7';
var COL_RUN = '#00B050';
var COL_STOP = '#A0A0A4';

var RANGES = { pt: [0.5, 6.0], flow: [0, 2000], level: [20, 90] };
var HIST_MAX = 40;
var hist = { 'iptran-spark-a': [], 'iptran-spark-b2': [], 'iptran-spark-b3': [], 'iptran-spark-c': [] };
var sparkGeo = {
  'iptran-spark-a':  { x: 200, y: 698, w: 150, h: 40 },
  'iptran-spark-b2': { x: 380, y: 698, w: 150, h: 40 },
  'iptran-spark-b3': { x: 560, y: 698, w: 150, h: 40 },
  'iptran-spark-c':  { x: 740, y: 698, w: 150, h: 40 }
};
var activeAlarms = {};
var lastUpdateMs = 0;

function setText(id, txt) {
  var el = document.getElementById(id);
  if (el) { el.textContent = txt; }
}
function setColor(id, color) {
  var el = document.getElementById(id);
  if (el) { el.setAttribute('fill', color); }
}
function setAlarm(id, value, lo, hi) {
  var n = parseFloat(value);
  var bad = (isNaN(n) || n < lo || n > hi);
  setColor(id, bad ? COL_ALARM : COL_NORMAL);
  return bad;
}
function setPumpState(id, on) {
  setColor(id, on ? COL_RUN : COL_STOP);
}
function toBool(v) {
  return v === true || v === 'true' || v === 1 || v === '1';
}
function setAlarmEntry(key, active, text) {
  if (active) { activeAlarms[key] = text; } else { delete activeAlarms[key]; }
  refreshAlarmUI();
}
function refreshAlarmUI() {
  var count = Object.keys(activeAlarms).length;
  var banner = document.getElementById('iptran-alarm-banner');
  var chip = document.getElementById('iptran-sys-chip');
  if (banner) { banner.style.display = (count > 0) ? 'inline' : 'none'; }
  if (chip) {
    if (count > 0) {
      chip.setAttribute('fill', COL_ALARM);
      chip.setAttribute('class', 'iptran-blink');
      setText('iptran-sys-text', count + ' ACTIVE ALARM' + (count > 1 ? 'S' : ''));
    } else {
      chip.setAttribute('fill', '#2E7D32');
      chip.removeAttribute('class');
      setText('iptran-sys-text', 'SYSTEM NORMAL');
    }
  }
  if (banner) {
    var texts = [];
    for (var k in activeAlarms) { texts.push(activeAlarms[k]); }
    setText('iptran-alarm-text', 'ALARM:  ' + texts.join('   |   '));
  }
}
function pushSpark(id, value, lo, hi) {
  var data = hist[id];
  if (!data) { return; }
  var n = parseFloat(value);
  if (!isNaN(n)) { data.push(n); }
  if (data.length > HIST_MAX) { data.shift(); }
  var g = sparkGeo[id];
  var el = document.getElementById(id);
  if (!el || data.length < 2) { return; }
  var pts = [];
  var step = g.w / (HIST_MAX - 1);
  for (var i = 0; i < data.length; i++) {
    var x = g.x + i * step;
    var norm = Math.min(Math.max((data[i] - lo) / (hi - lo), 0), 1);
    var y = g.y + g.h - norm * g.h;
    pts.push(x.toFixed(1) + ',' + y.toFixed(1));
  }
  el.setAttribute('points', pts.join(' '));
}
function setFlowAnimation(id, flow) {
  var el = document.getElementById(id);
  if (!el) { return; }
  if (flow > 0) {
    el.classList.add('iptran-flow-on');
    var speed = Math.max(0.4, Math.min(2.5, 2400 / (flow + 400)));
    el.style.animationDuration = speed.toFixed(2) + 's';
  } else {
    el.classList.remove('iptran-flow-on');
  }
}
function setCommState(station, online) {
  var grp = document.getElementById('iptran-station-' + station);
  var warn = document.getElementById('iptran-linkdown-' + station);
  if (grp) { grp.setAttribute('opacity', online ? '1' : '0.5'); }
  if (warn) { warn.style.display = online ? 'none' : 'inline'; }
  var commKey = 'COMM-' + station;
  setAlarmEntry(commKey, !online, 'COMM-' + station + ' link down');
}

function putValue(id, value) {
  lastUpdateMs = Date.now();
  if (id === '_ps_stationA_pt') {
    _ps_stationA_pt = value;
    setText('iptran-val-a-pt', value);
    setAlarmEntry('PT-01', setAlarm('iptran-val-a-pt', value, RANGES.pt[0], RANGES.pt[1]), 'PT-01 ' + value + ' bar');
    pushSpark('iptran-spark-a', value, RANGES.pt[0], RANGES.pt[1]);
  } else if (id === '_ps_stationB_pt2') {
    _ps_stationB_pt2 = value;
    setText('iptran-val-b-pt2', value);
    setAlarmEntry('PT-02', setAlarm('iptran-val-b-pt2', value, RANGES.pt[0], RANGES.pt[1]), 'PT-02 ' + value + ' bar');
    pushSpark('iptran-spark-b2', value, RANGES.pt[0], RANGES.pt[1]);
  } else if (id === '_ps_stationB_pt3') {
    _ps_stationB_pt3 = value;
    setText('iptran-val-b-pt3', value);
    setAlarmEntry('PT-03', setAlarm('iptran-val-b-pt3', value, RANGES.pt[0], RANGES.pt[1]), 'PT-03 ' + value + ' bar');
    pushSpark('iptran-spark-b3', value, RANGES.pt[0], RANGES.pt[1]);
  } else if (id === '_ps_stationC_pt') {
    _ps_stationC_pt = value;
    setText('iptran-val-c-pt', value);
    setAlarmEntry('PT-04', setAlarm('iptran-val-c-pt', value, RANGES.pt[0], RANGES.pt[1]), 'PT-04 ' + value + ' bar');
    pushSpark('iptran-spark-c', value, RANGES.pt[0], RANGES.pt[1]);
  } else if (id === '_pn_stationA_flow') {
    _pn_stationA_flow = Number(value) || 0;
    setText('iptran-val-a-fm', _pn_stationA_flow.toFixed(1));
    setAlarmEntry('FM-A', setAlarm('iptran-val-a-fm', _pn_stationA_flow, RANGES.flow[0], RANGES.flow[1]), 'FM-A ' + _pn_stationA_flow.toFixed(1) + ' m3/h');
    setFlowAnimation('iptran-flow-ab', _pn_stationA_flow);
    var barA = document.getElementById('iptran-load-bar');
    if (barA) { barA.setAttribute('width', (120 * Math.min(_pn_stationA_flow / RANGES.flow[1], 1)).toFixed(0)); }
    setText('iptran-load-text', 'A: ' + _pn_stationA_flow.toFixed(0) + ' m3/h');
  } else if (id === '_pn_stationB_flow') {
    _pn_stationB_flow = Number(value) || 0;
    setText('iptran-val-b-fm', _pn_stationB_flow.toFixed(1));
    setAlarmEntry('FM-B', setAlarm('iptran-val-b-fm', _pn_stationB_flow, RANGES.flow[0], RANGES.flow[1]), 'FM-B ' + _pn_stationB_flow.toFixed(1) + ' m3/h');
  } else if (id === '_pn_stationC_flow') {
    _pn_stationC_flow = Number(value) || 0;
    setText('iptran-val-c-fm', _pn_stationC_flow.toFixed(1));
    setAlarmEntry('FM-C', setAlarm('iptran-val-c-fm', _pn_stationC_flow, RANGES.flow[0], RANGES.flow[1]), 'FM-C ' + _pn_stationC_flow.toFixed(1) + ' m3/h');
    setFlowAnimation('iptran-flow-bc', _pn_stationC_flow);
    setText('iptran-load-text2', 'C: ' + _pn_stationC_flow.toFixed(0) + ' m3/h');
  } else if (id === '_pn_stationB_level') {
    _pn_stationB_level = Number(value) || 0;
    setText('iptran-val-b-lt', _pn_stationB_level.toFixed(1));
    setAlarmEntry('LT-01', setAlarm('iptran-val-b-lt', _pn_stationB_level, RANGES.level[0], RANGES.level[1]), 'LT-01 ' + _pn_stationB_level.toFixed(1) + ' %');
  } else if (id === '_pb_pumpA_run') {
    _pb_pumpA_run = toBool(value);
    setPumpState('iptran-pump-a', _pb_pumpA_run);
  } else if (id === '_pb_pumpB_run') {
    _pb_pumpB_run = toBool(value);
    setPumpState('iptran-pump-b', _pb_pumpB_run);
  } else if (id === '_pb_commA') {
    _pb_commA = toBool(value);
    setColor('iptran-comm-a', _pb_commA ? COL_RUN : COL_ALARM);
    setCommState('a', _pb_commA);
  } else if (id === '_pb_commB') {
    _pb_commB = toBool(value);
    setColor('iptran-comm-b', _pb_commB ? COL_RUN : COL_ALARM);
    setCommState('b', _pb_commB);
  } else if (id === '_pb_commC') {
    _pb_commC = toBool(value);
    setColor('iptran-comm-c', _pb_commC ? COL_RUN : COL_ALARM);
    setCommState('c', _pb_commC);
  }
}

function togglePumpCmd(id) {
  if (id === 'iptran-pump-a') {
    _pb_pumpA_cmd = !_pb_pumpA_cmd;
    if (typeof postValue === 'function') { postValue('_pb_pumpA_cmd', _pb_pumpA_cmd); }
  } else if (id === 'iptran-pump-b') {
    _pb_pumpB_cmd = !_pb_pumpB_cmd;
    if (typeof postValue === 'function') { postValue('_pb_pumpB_cmd', _pb_pumpB_cmd); }
  }
  var el = document.getElementById(id);
  if (el) {
    el.classList.add('iptran-pulse');
    setTimeout(function () { el.classList.remove('iptran-pulse'); }, 600);
  }
}

function iptranTick() {
  if (!document.getElementById('iptran-widget-root')) {
    clearInterval(iptranTimer);
    return;
  }
  var now = new Date();
  setText('iptran-clock', now.toLocaleTimeString());
  setText('iptran-date', now.toLocaleDateString());
  var live = document.getElementById('iptran-live-text');
  if (live) {
    if (lastUpdateMs === 0) {
      live.setAttribute('fill', '#919191');
      setText('iptran-live-text', 'WAITING FOR DATA');
    } else if (Date.now() - lastUpdateMs > 15000) {
      live.setAttribute('fill', '#E65100');
      setText('iptran-live-text', 'STALE DATA ' + Math.round((Date.now() - lastUpdateMs) / 1000) + 's');
    } else {
      live.setAttribute('fill', '#2E7D32');
      setText('iptran-live-text', 'LIVE DATA');
    }
  }
}
var iptranTimer = setInterval(iptranTick, 1000);

function iptranInit() {
  ['iptran-pump-a', 'iptran-pump-b'].forEach(function (id) {
    var el = document.getElementById(id);
    if (el) {
      el.addEventListener('click', function () { togglePumpCmd(id); });
    }
  });
  iptranTick();
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', iptranInit);
} else {
  iptranInit();
}
//
